def round_end(rid, prs, repo=None):
    rounds = _read("rounds", repo)
    for r in rounds:
        if r.get("round") == rid:
            r["ended_at"] = _now()
            r["prs"] = prs
    with open(_path("rounds", repo), "w") as f:
        for r in rounds:
            f.write(json.dumps(r, separators=(",", ":")) + "\n")
